	/** Return one <svg><use></svg> tag. */
	public static function icon( $id, $class = 'apx-icon' ) {
		return sprintf(
			'<svg class="%s" aria-hidden="true"><use href="#apx-i-%s"></use></svg>',
			esc_attr( $class ),
			esc_attr( $id )
		);
